import os, sqlite3, sys

sys.path.insert(0, os.getcwd())
from src.repository import balance, initialize
from src.service import transfer
from src.events import Recorder


def fresh():
    c = sqlite3.connect(":memory:")
    initialize(c)
    c.executemany("INSERT INTO accounts VALUES (?, ?)", [("a", 100), ("b", 20)])
    c.commit()
    return c


class Proxy:
    """Stands in for the connection while failing selected operations."""

    def __init__(self, conn, fail=()):
        self._conn = conn
        self._fail = set(fail)
        self.executes = 0

    def execute(self, sql, params=()):
        self.executes += 1
        if ("execute", self.executes) in self._fail:
            raise RuntimeError("boom-execute-%d" % self.executes)
        return self._conn.execute(sql, params)

    def commit(self):
        if ("commit",) in self._fail:
            raise RuntimeError("boom-commit")
        return self._conn.commit()

    def rollback(self):
        return self._conn.rollback()


def assert_untouched(c, p):
    assert (balance(c, "a"), balance(c, "b")) == (100, 20)
    assert c.execute("SELECT COUNT(*) FROM ledger").fetchone()[0] == 0
    assert p.events == []
    assert not c.in_transaction


def check(name, fn):
    fn()
    print("ok -", name)


# 1. Happy path: exactly one debit, one credit, one ledger row, commit, publish.
def t_happy():
    c, p = fresh(), Recorder()
    transfer(c, p, "a", "b", 10)
    assert (balance(c, "a"), balance(c, "b")) == (90, 30)
    assert c.execute("SELECT COUNT(*) FROM ledger").fetchone()[0] == 1
    assert c.execute("SELECT * FROM ledger").fetchall() == [("a", "b", 10)]
    assert p.events == [{"source": "a", "target": "b", "amount": 10}]
    assert not c.in_transaction


def t_happy_amount_equals_balance():
    c, p = fresh(), Recorder()
    transfer(c, p, "a", "b", 100)
    assert (balance(c, "a"), balance(c, "b")) == (0, 120)
    assert p.events == [{"source": "a", "target": "b", "amount": 100}]


# 2. Invalid transfers raise ValueError with no writes, no publication, idle connection.
def t_same_account():
    c, p = fresh(), Recorder()
    try:
        transfer(c, p, "a", "a", 10)
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError")
    assert_untouched(c, p)


def t_bad_amounts():
    for amount in (True, False, 0, -1, -100, 1.0, 10.5, "10", None, [10]):
        c, p = fresh(), Recorder()
        try:
            transfer(c, p, "a", "b", amount)
        except ValueError:
            pass
        else:
            raise AssertionError("expected ValueError for %r" % (amount,))
        assert_untouched(c, p)


