# 3. Database failure while validating: rollback, no publication, error propagates.
def t_failure_during_balance_read():
    c = fresh()
    p = Recorder()
    proxy = Proxy(c, fail=(("execute", 1),))
    try:
        transfer(proxy, p, "a", "b", 10)
    except RuntimeError as e:
        assert "boom-execute-1" in str(e)
    else:
        raise AssertionError("expected RuntimeError")
    assert (balance(c, "a"), balance(c, "b")) == (100, 20)
    assert c.execute("SELECT COUNT(*) FROM ledger").fetchone()[0] == 0
    assert p.events == []
    assert not c.in_transaction


# 4. Database failure at any write statement: full rollback, no publication.
def t_failure_each_write():
    for n in (3, 4, 5):  # 1,2 are reads; 3 debit, 4 credit, 5 ledger insert
        c = fresh()
        p = Recorder()
        proxy = Proxy(c, fail=(("execute", n),))
        try:
            transfer(proxy, p, "a", "b", 10)
        except RuntimeError as e:
            assert "boom-execute-%d" % n in str(e)
        else:
            raise AssertionError("expected RuntimeError at statement %d" % n)
        assert (balance(c, "a"), balance(c, "b")) == (100, 20)
        assert c.execute("SELECT COUNT(*) FROM ledger").fetchone()[0] == 0
        assert p.events == []
        assert not c.in_transaction


# 5. Commit failure: full rollback, no publication.
def t_failure_on_commit():
    c = fresh()
    p = Recorder()
    proxy = Proxy(c, fail=(("commit",),))
    try:
        transfer(proxy, p, "a", "b", 10)
    except RuntimeError as e:
        assert "boom-commit" in str(e)
    else:
        raise AssertionError("expected RuntimeError")
    assert (balance(c, "a"), balance(c, "b")) == (100, 20)
    assert c.execute("SELECT COUNT(*) FROM ledger").fetchone()[0] == 0
    assert p.events == []
    assert not c.in_transaction


# 6. Publication failure: propagates but committed transfer is not undone.
def t_publish_failure_keeps_commit():
    c = fresh()

    class BadPublisher:
        def publish(self, event):
            raise RuntimeError("bus down")

    p_events = []
    p = BadPublisher()
    try:
        transfer(c, p, "a", "b", 10)
    except RuntimeError as e:
        assert "bus down" in str(e)
    else:
        raise AssertionError("expected RuntimeError")
    assert (balance(c, "a"), balance(c, "b")) == (90, 30)
    assert c.execute("SELECT COUNT(*) FROM ledger").fetchone()[0] == 1
    assert not c.in_transaction


# 7. Publisher receives exactly the requested event dict.
def t_publish_payload():
    c, seen = fresh(), []

    class Capture:
        def publish(self, event):
            seen.append(event)

    transfer(c, Capture(), "a", "b", 7)
    assert seen == [{"source": "a", "target": "b", "amount": 7}]
    assert seen[0] == {"source": "a", "target": "b", "amount": 7}
    assert list(seen[0].items()) == [("source", "a"), ("target", "b"), ("amount", 7)]


check("happy path", t_happy)
check("amount equal to balance allowed", t_happy_amount_equals_balance)
