check("missing target rejected", t_missing_target)
check("insufficient funds rejected", t_insufficient)
check("insufficient funds rejected (reverse direction)", t_insufficient_target_acct_valid)
check("failure during balance read", t_failure_during_balance_read)
check("failure at each write statement", t_failure_each_write)
check("commit failure", t_failure_on_commit)
check("publish failure keeps commit", t_publish_failure_keeps_commit)
check("publish payload", t_publish_payload)
